import type { Knex } from 'knex';

/**
 * JGN clinical-chemistry catalog import. Sourced from jgn-items.xlsx
 * (sheet: 'clinical chemistry'). Generated by _tmp_xlsx/build_mapping.py
 * — regenerate rather than editing this file by hand.
 *
 * Duplicate itemcodes in the source (CC014/015/016 reused twice) were
 * renumbered: PHOSPHORUS → CC021, ALKALINE PHOSPHATASE → CC022,
 * BILIRUBIN → CC023.
 *
 * Runs via env vars so the same seed can target any tenant + category:
 *   JGN_TENANT_UUID=<uuid> JGN_CATEGORY_UUID=<uuid> \
 *     npx knex seed:run --specific 08_seed_jgn_chemistry.ts
 *
 * Also exported as seedJgnChemistry(knex, opts) for direct calls from
 * scripts or other seeds.
 *
 * Idempotent — checks (tenant_uuid, code) before inserting; components
 * checked by (test_item_uuid, code). Existing rows are left untouched.
 */

