export interface SeedJgnChemistryOptions {
	tenant_uuid: string;
	item_category_uuid: string;
	created_by?: string;
}

export interface SeedJgnChemistryResult {
	items_inserted: number;
	items_skipped: number;
	components_inserted: number;
}

export async function seedJgnChemistry(
	knex: Knex,
	opts: SeedJgnChemistryOptions,
): Promise<SeedJgnChemistryResult> {
	const { tenant_uuid, item_category_uuid } = opts;
	const created_by = opts.created_by ?? 'seed:08_seed_jgn_chemistry';
	let items_inserted = 0;
	let items_skipped = 0;
	let components_inserted = 0;

	for (const item of ITEMS) {
		let row = await knex('test_items')
			.where({ tenant_uuid, code: item.code })
			.first();
		if (row) {
			items_skipped += 1;
		} else {
			const [inserted] = await knex('test_items')
				.insert({
					tenant_uuid,
					item_category_uuid,
					code: item.code,
					name: item.name,
					result_type: item.result_type,
					unit_of_measure: item.unit_of_measure,
					reference_range: item.reference_range,
					si_conversion_factor: item.si_conversion_factor,
					si_unit_of_measure: item.si_unit_of_measure,
					si_reference_range: item.si_reference_range,
					price: item.price,
					status: 'active',
					created_by,
				})
				.returning('*');
			row = inserted;
			items_inserted += 1;
		}

		if (item.result_type === 'panel' && item.components.length) {
			for (const c of item.components) {
				const exists = await knex('test_item_components')
					.where({ test_item_uuid: row.uuid, code: c.code })
					.first();
				if (exists) continue;
				await knex('test_item_components').insert({
					tenant_uuid,
					test_item_uuid: row.uuid,
					code: c.code,
					name: c.name,
					unit_of_measure: c.unit_of_measure,
					reference_range: c.reference_range,
					si_conversion_factor: c.si_conversion_factor,
					si_unit_of_measure: c.si_unit_of_measure,
					si_reference_range: c.si_reference_range,
					display_order: c.display_order,
					created_by,
				});
				components_inserted += 1;
			}
		}
	}

	return { items_inserted, items_skipped, components_inserted };
}

export async function seed(knex: Knex): Promise<void> {
	const tenant_uuid = process.env.JGN_TENANT_UUID;
	const item_category_uuid = process.env.JGN_CATEGORY_UUID;
	if (!tenant_uuid || !item_category_uuid) {
		// eslint-disable-next-line no-console
		console.warn(
			'[seed 08] Skipped — set JGN_TENANT_UUID and JGN_CATEGORY_UUID env vars, ' +
				'or import seedJgnChemistry() and call it directly with your ids.',
		);
		return;
	}
	const result = await seedJgnChemistry(knex, { tenant_uuid, item_category_uuid });
	// eslint-disable-next-line no-console
	console.log(
		`[seed 08] Items inserted=${result.items_inserted} skipped=${result.items_skipped}, ` +
			`components inserted=${result.components_inserted}`,
	);
}
